// === Tab: mySketch ===
// Attractor_15.1

let N = 4000 ; 
let S = 0.02 ; let G = 0.0045 ; let H = 0.0203 ; let CX = 120 ; let CY = 50 ;

let X[] = new Array(N) ; let Y[] = new Array(N) ; let Z[] = new Array(N) ;
let KX ; let KY ; let L ; let KdX ; let KdY ; let dX ; let dY ; let dZ ;
let I ; let NX ; let NY ; let NZ ; let KN ;

function setup(){

  createCanvas(600, 600) ; noSmooth() ; background(0) ; stroke(255) ; textSize(20) ;

  KX = random(20,100) ; KY = random(20,80) ;
  for ( I = 0 ; I < N ; I++ ){
    X[I] = random(0,120) ; Y[I] = 0 ; Z[I] = random(0,100) ; 
    L = sqrt(pow(X[I]-KX,2)+pow(Z[I]-KY,2)) ;
    if ( L < 20 ){ I = I-1 ; }
  }
  KN = N ;

}// setup()

function draw(){

  if ( KN == N ){ fill(0,0,0,40) ; rect(-1,-1,601,601) ; fill(255) ; }
  line(50,400,550,400) ; line(550,400,540,390) ; line(550,400,540,410) ; text("X",560,405) ;
  line(350,50,350,550) ; line(350,50,340,60) ; line(350,50,360,60) ; text("Z",345,40) ;
  line(500,250,200,550) ; line(200,550,200,535) ; line(200,550,215,550) ; text("Y",180,570) ;

  for ( I = 0 ; I < KN ; I++ ){

    if ( Y[I] >= 0 ){
      L = sqrt(pow(X[I],2)+pow(Y[I],2)) ;
      KX = L ; KY = Z[I] ;
      KdX = +KX*G ; KdY = -KY*G ;
    }else{
      L = sqrt(pow(X[I],2)+pow(Y[I],2)) ;
      KX = L ; KY = Z[I] ;
      if ( KX > CX || KY > CY ){
        KdX = (-KY+CY)*H ; KdY = (+KX-CX)*H ;
      }else{ KdX = 0 ; KdY = 0 ; }
    }
    dX = KdX*X[I]/L + (-Y[I]*S) ; dY = KdX*Y[I]/L + (X[I]*S) ; dZ = KdY ;
    NX = X[I] + dX ; NY = Y[I] + dY ; NZ = Z[I] + dZ ;
    line(X[I]-(Y[I]/2)+350,-Z[I]+(Y[I]/2)+400,NX-(NY/2)+350,-NZ+(NY/2)+400) ;
    X[I] = NX ; Y[I] = NY ; Z[I] = NZ ;    

  }// I

}// draw()

function mousePressed(){

  background(0) ;

  if ( KN != N ){ 
    KN = N ; 
    for ( I = 1 ; I < N ; I++ ){
      X[I] = X[0] + random(-1,+1) ;
      Y[I] = Y[0] + random(-1,+1) ;
      Z[I] = Z[0] + random(-1,+1) ;
    }
  }else{ KN = 1 ; }

}// mousePressed()

